import { useLocation } from 'react-router-dom';
import './find.css';
import React, { useEffect, useState } from "react";
import Axios from "axios";

function Find() {
  const [data, setUserList] = useState([]);
  const [filteredData, setFilteredData] = useState([]);
  const [years, setYears] = useState([]);
  const [selectedYear, setSelectedYear] = useState('');
  const location = useLocation();

  const getuser = async () => {
    try {
      const response = await Axios.get("http://localhost:3002/getdetails");
      const users = response.data.users || [];
      setUserList(users);

      const uniqueYears = [...new Set(users.map((user) => user.year))].sort();
      setYears(uniqueYears);

      // Initial filtering based on selectedYear
      setFilteredData(selectedYear ? users.filter(user => user.year === selectedYear) : users);
    } catch (error) {
      console.error("fetching error", error);
    }
  };

  useEffect(() => {
    getuser();
  }, [location]);

  useEffect(() => {
    const filtered = selectedYear
      ? data.filter(user => user.year === selectedYear)
      : data;
    setFilteredData(filtered);
  }, [selectedYear, data]);

  return (
    <div className="find-container">
      <div className="card">
        <h2 className="title">University Course Records</h2>

        <div className="filter-group">
          <label htmlFor="year">Filter by Year:</label>
          <select
            id="year"
            value={selectedYear}
            onChange={(e) => setSelectedYear(e.target.value)}
            className="year-select"
          >
            <option value="">All Years</option>
            {years.map((year, index) => (
              <option key={index} value={year}>{year}</option>
            ))}
          </select>
        </div>

        <div className="table-wrapper">
          <table className="styled-table">
            <thead>
              <tr>
                <th>District</th>
                <th>Stream</th>
                <th>Course</th>
                <th>Campus</th>
                <th>Subject 1</th>
                <th>Subject 2</th>
                <th>Subject 3</th>
                <th>Z-Range</th>
                <th>Students</th>
                <th>Year</th>
              </tr>
            </thead>
            <tbody>
              {filteredData.length > 0 ? (
                filteredData.map((row, index) => (
                  <tr key={index}>
                    <td>{row.district || 'N/A'}</td>
                    <td>{row.stream || 'N/A'}</td>
                    <td>{row.course || 'N/A'}</td>
                    <td>{row.campus || 'N/A'}</td>
                    <td>{row.subject1 || 'N/A'}</td>
                    <td>{row.subject2 || 'N/A'}</td>
                    <td>{row.subject3 || 'N/A'}</td>
                    <td>{row.zValue1 && row.zValue2 ? `${row.zValue1} - ${row.zValue2}` : 'N/A'}</td>
                    <td>{row.Students || 0}</td>
                    <td>{row.year || 'N/A'}</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="10" className="no-data">
                    No data available for the selected year.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

export default Find;
